void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  vec3 bg = mix(MP_INK, MP_DEEP, length(p) * 1.3);
  float k = eOut(ramp(0.1, 0.85));
  vec4 lg = mpLogo(p, vec2(0.0, 0.07), 0.15, (1.0 - k) * 4.0, ramp(0.75, 1.05));
  vec3 col = mix(bg, lg.rgb, lg.a);
  col += MP_CYAN * 0.25 * exp(-length(p - vec2(0.0, 0.07)) * 9.0) * (ramp(0.8, 0.9) - ramp(0.9, 1.6));
  col = mix(col, MP_WHITE, textFill(wordmark, uv + vec2(0.0, 0.025 * (1.0 - eOut(ramp(0.9, 1.6))))) * ramp(0.9, 1.4));
  fragColor = vec4(mix(col, bg, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  vec3 bg = mix(MP_INK, MP_DEEP, length(p) * 1.3);
  vec2 c = vec2(0.0, 0.07);
  float a = (1.0 - eOut(ramp(0.05, 1.2))) * 9.42478;
  float cs = cos(a);
  float sx = max(abs(cs), 0.02);
  vec2 q = vec2((p.x - c.x) / sx * sign(cs + 1e-4), p.y - c.y) + c;
  float sc = mix(0.6, 1.0, eOut(ramp(0.05, 1.2)));
  vec4 lg = mpLogo(q, c, 0.15 * sc, 0.0, 1.0);
  lg.rgb *= mix(0.55, 1.0, abs(cs));
  vec3 col = mix(bg, lg.rgb, lg.a * step(abs(p.x - c.x), 0.15 * sc * sx + 0.01) * ramp(0.05, 0.2));
  float g = (p.x + (p.y - c.y) * 0.6) - mix(-0.3, 0.3, ramp(1.25, 1.75));
  col += vec3(0.6) * exp(-g * g * 900.0) * lg.a * step(1.25, mpT()) * (1.0 - ramp(1.7, 1.8));
  col = mix(col, MP_WHITE, textFill(wordmark, uv) * ramp(1.2, 1.6));
  fragColor = vec4(mix(col, bg, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  vec3 bg = mix(MP_INK, MP_DEEP, length(p) * 1.3);
  vec2 c = vec2(0.0, 0.07); float r = 0.15;
  vec2 q = (p - c) / r;
  float ang = (atan(q.x, q.y) + 3.14159) / 6.28318;
  float prog = eInOut(ramp(0.1, 1.2));
  float drawn = step(1.0 - ang, prog);
  float w = px() / r;
  float lw = 2.2 * w;
  vec3 col = bg;
  col = mix(col, MP_BLUE, (1.0 - smoothstep(lw * 0.5, lw, abs(sdBlue(q)))) * drawn);
  col = mix(col, MP_CYAN, (1.0 - smoothstep(lw * 0.5, lw, abs(sdCyan(q)))) * drawn);
  col = mix(col, MP_WHITE, (1.0 - smoothstep(lw * 0.5, lw, abs(min(sdLensL(q), sdLensR(q))))) * step(1.0 - ang, prog - 0.12));
  vec4 lg = mpLogo(p, c, r, 0.0, 1.0);
  col = mix(col, lg.rgb, lg.a * ramp(1.15, 1.55));
  col = mix(col, MP_WHITE, textFill(wordmark, uv) * step(uv.x, mix(wordmarkBox.x, wordmarkBox.z + 0.01, ramp(1.3, 1.9))));
  fragColor = vec4(mix(col, bg, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  vec3 bg = MP_DEEP;
  bg += vec3(0.6) * step(0.997, hash12(floor(p * 220.0))) * 0.5;   // a few stars
  vec2 c = vec2(0.0, 0.07); float r = 0.15;
  vec4 lg = mpLogo(p, c, r, 0.0, 1.0);
  vec3 col = mix(bg, lg.rgb, lg.a);
  float m = eInOut(ramp(0.55, 1.5));
  vec2 oc = c + vec2(m * 0.42, m * 0.12);
  float od = length(p - oc) - r * 1.03;
  float corona = exp(-max(od, 0.0) / 0.018) * (0.4 + 0.6 * ramp(0.0, 0.5)) * (1.0 - m);
  float rays = 0.6 + 0.4 * fbm(vec2(atan(p.y - oc.y, p.x - oc.x) * 3.0, mpT() * 0.6));
  col += MP_CYAN * corona * rays * step(0.0, od);
  col = mix(col, bg * 0.6, cover(od, px()) * (1.0 - ramp(1.45, 1.5)));
  col = mix(col, MP_WHITE, textFill(wordmark, uv) * ramp(1.35, 1.8));
  fragColor = vec4(mix(col, MP_DEEP, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  float t = mpT();
  vec3 bg = mix(MP_INK, MP_DEEP, length(p) * 1.3);
  vec2 c = vec2(0.0, 0.07); float r = 0.15;
  vec2 q = (p - c) / r;
  float w = px() / r;
  float calm = 1.0 - ramp(1.4, 1.9);
  float lvL = mix(-1.15, 1.15, eInOut(ramp(0.1, 1.3))) + 0.07 * sin(q.x * 7.0 + t * 8.0) * calm;
  float lvR = mix(-1.15, 1.15, eInOut(ramp(0.3, 1.5))) + 0.07 * sin(q.x * 7.0 - t * 8.0 + 1.0) * calm;
  vec3 col = bg;
  float ring = 1.0 - smoothstep(w, w * 2.5, abs(sdDisc(q)));
  col = mix(col, MP_WHITE * 0.35, ring * 0.6 * (1.0 - ramp(1.3, 1.6)));
  col = mix(col, MP_BLUE, cover(sdBlue(q), w) * step(q.y, lvL));
  col = mix(col, MP_CYAN, cover(sdCyan(q), w) * step(q.y, lvR));
  col = mix(col, MP_WHITE, cover(min(sdLensL(q), sdLensR(q)), w) * ramp(1.45, 1.75));
  col = mix(col, MP_WHITE, textFill(wordmark, uv) * ramp(1.5, 1.9));
  fragColor = vec4(mix(col, bg, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  vec3 bg = mix(vec3(0.05, 0.16, 0.25), MP_DEEP, length(p - vec2(-0.3, 0.1)) * 1.1);
  vec2 c = vec2(-0.31, 0.0);
  float s = max(eBack(ramp(0.1, 0.65)), 1e-3);
  vec2 q = (p - c) / s;
  float half_ = 0.18;
  float td = sdRBox(q, vec2(half_), 0.04);
  float shadow = exp(-max(sdRBox(p - c - vec2(0.0, -0.025), vec2(half_ * s), 0.04 * s), 0.0) / 0.03) * 0.45 * ramp(0.1, 0.5);
  vec3 col = bg * (1.0 - shadow);
  col = mix(col, MP_INK, cover(td, px() / s));
  vec4 lg = mpLogo(q, vec2(0.0), 0.12, 0.0, 1.0);
  col = mix(col, lg.rgb, lg.a * cover(td, px()));
  float k = eOut(ramp(0.6, 1.3));
  float tm = smoothstep(0.43, 0.445, uv.x);
  col = mix(col, MP_WHITE, textFill(wordmark, uv + vec2(0.12 * (1.0 - k), 0.0)) * tm);
  fragColor = vec4(mix(col, bg, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  vec3 bg = mix(MP_INK, MP_DEEP, length(p) * 1.3);
  vec2 c = vec2(0.0, 0.07); float r = 0.15;
  float cw = 0.012;
  float col_id = floor((p.x - c.x) / cw);
  float h = hash12(vec2(col_id, 3.0));
  float d0 = 0.1 + h * 0.6 + abs(col_id) * 0.012;
  float k = eBack(ramp(d0, d0 + 0.5));
  float off = (1.0 - k) * 0.9;
  vec4 lg = mpLogo(p - vec2(0.0, off), c, r, 0.0, 1.0);
  float edge = smoothstep(0.0, px() * 1.5, abs(fract((p.x - c.x) / cw) - 0.5) * cw - cw * 0.5 + px() * 1.5);
  lg.rgb *= mix(1.0, 0.82 + 0.18 * h, 1.0 - ramp(d0 + 0.4, d0 + 0.7));
  vec3 col = mix(bg, lg.rgb, lg.a);
  col = mix(col, MP_WHITE, textFill(wordmark, uv) * ramp(1.3, 1.7));
  fragColor = vec4(mix(col, bg, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  float t = mpT();
  vec3 bg = MP_DEEP * (0.8 + 0.4 * fbm(p * 18.0));
  vec2 c = vec2(0.0, 0.07); float r = 0.15;
  vec2 q = (p - c) / r;
  float fl = step(0.45, hash12(vec2(floor(t * 22.0), 1.0)));
  float onL = t < 0.25 ? 0.0 : (t < 0.75 ? fl : 1.0);
  float onR = t < 0.5 ? 0.0 : (t < 1.0 ? step(0.45, hash12(vec2(floor(t * 19.0), 7.0))) : 1.0);
  float onW = t < 0.9 ? 0.0 : (t < 1.25 ? step(0.4, hash12(vec2(floor(t * 25.0), 3.0))) : 1.0);
  vec3 col = bg;
  float dB = abs(sdBlue(q)) * r, dC = abs(sdCyan(q)) * r, dW = abs(min(sdLensL(q), sdLensR(q))) * r;
  col += MP_BLUE * exp(-dB / 0.014) * 0.7 * onL;
  col += MP_CYAN * exp(-dC / 0.014) * 0.7 * onR;
  col += MP_WHITE * exp(-dW / 0.012) * 0.45 * onW;
  col = mix(col, mix(MP_BLUE, vec3(1.0), 0.55), (1.0 - smoothstep(0.0015, 0.003, dB)) * onL);
  col = mix(col, mix(MP_CYAN, vec3(1.0), 0.55), (1.0 - smoothstep(0.0015, 0.003, dC)) * onR);
  col = mix(col, vec3(1.0), (1.0 - smoothstep(0.0015, 0.003, dW)) * onW);
  float on2 = t < 1.3 ? 0.0 : (t < 1.6 ? step(0.4, hash12(vec2(floor(t * 23.0), 9.0))) : 1.0);
  float wd = textDistance(wordmark, uv);
  col += MP_CYAN * pow(textHalo(wordmark, uv), 4.0) * 0.5 * on2;
  col = mix(col, vec3(0.92, 0.98, 1.0), (1.0 - smoothstep(0.001, 0.0025, abs(wd))) * on2);
  fragColor = vec4(mix(col, bg, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  float t = mpT();
  vec3 bg = mix(MP_INK, MP_DEEP, length(p) * 1.3);
  float hit = 1.0;
  float shake = (1.0 - ramp(hit, hit + 0.3)) * step(hit, t);
  p += vec2(sin(t * 90.0), cos(t * 77.0)) * 0.006 * shake;
  vec2 c = vec2(0.0, 0.07); float r = 0.15;
  float k = eInOut(ramp(0.05, hit));
  float u = 1.0 - k;
  vec2 pa = c + rot(-0.9 * u) * (p - c - vec2(-0.55, 0.22) * u);
  vec2 pb = c + rot(0.9 * u) * (p - c - vec2(0.55, -0.22) * u);
  float aa = mpLogo(pa, c, r, 0.0, 1.0).a, ab = mpLogo(pb, c, r, 0.0, 1.0).a;
  vec3 col = bg;
  col += MP_BLUE * aa * 0.75 * (1.0 - step(hit, t));
  col += MP_CYAN * ab * 0.75 * (1.0 - step(hit, t));
  vec4 lg = mpLogo(p, c, r, 0.0, 1.0);
  col = mix(col, lg.rgb, lg.a * step(hit, t));
  float rr = (t - hit) * 0.8;
  col += MP_WHITE * (1.0 - smoothstep(0.0, 0.006, abs(length(p - c) - r - rr))) * (1.0 - ramp(hit, hit + 0.6)) * step(hit, t);
  col += MP_WHITE * 0.5 * exp(-length(p - c) * 6.0) * (1.0 - ramp(hit, hit + 0.25)) * step(hit, t);
  col = mix(col, MP_WHITE, textFill(wordmark, uv) * ramp(1.3, 1.7));
  fragColor = vec4(mix(col, bg, ramp(uDuration - 0.35, uDuration)), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  // Dark ground. At the end the grid, the drafting and the name fade but the icon stays, so the
  // "Through the gap" intro can pick it up where it is (centre 0, 0.07, radius 0.15).
  float leave = 1.0 - ramp(uDuration - 0.4, uDuration);
  vec3 ground = MP_DEEP * 0.75;
  vec3 bg = ground;
  vec2 g = abs(fract(p * 20.0 + 0.5) - 0.5) / 20.0;
  bg = mix(bg, MP_BLUE, (1.0 - smoothstep(0.0, px() * 1.2, min(g.x, g.y))) * 0.05 * leave);
  vec2 c = vec2(0.0, 0.07); float r = 0.15;
  vec2 q = (p - c) / r;
  float lw = 1.3 * px() / r;
  float ang = (atan(q.y, q.x) + 3.14159) / 6.28318;
  float dash = step(0.5, fract(ang * 48.0));
  vec3 col = bg;
  float c1 = (1.0 - smoothstep(0.0, lw, abs(sdDisc(q)))) * step(ang, eOut(ramp(0.05, 0.6)));
  float v = (1.0 - smoothstep(0.0, lw, abs(abs(q.x) - 0.278))) * step(abs(q.y), 1.25 * eOut(ramp(0.35, 0.75)));
  float a1 = length(q - vec2(-0.637, 0.0)), a2 = length(q - vec2(0.637, 0.0));
  float arcs = (1.0 - smoothstep(0.0, lw, min(abs(a1 - 0.634), abs(a2 - 0.634)))) * ramp(0.6, 0.9) * dash;
  float cross_ = (1.0 - smoothstep(0.0, lw, min(abs(q.x), abs(q.y)))) * step(length(q), 1.35) * ramp(0.1, 0.4) * 0.5;
  float marks = max(max(c1, v), max(arcs, cross_));
  col = mix(col, MP_CYAN, marks * (1.0 - 0.6 * ramp(1.2, 1.6)) * leave);
  vec4 lg = mpLogo(p, c, r, 0.0, 1.0);
  float ink = step(q.x, mix(-1.1, 1.1, eInOut(ramp(0.95, 1.45))));
  col = mix(col, lg.rgb, lg.a * ink);
  col = mix(col, MP_WHITE, textFill(wordmark, uv) * ramp(1.4, 1.8) * leave);
  fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution;
  float k = eInOut(ramp(0.25, 1.3));
  float edge = 0.5 * (1.0 - k) - 0.1 * k;           // where each panel's flat side sits
  float yy = (uv.y - 0.5) * 2.0;
  float bulge = 0.07 * sqrt(max(0.0, 1.0 - yy * yy)); // the lens, bowed like the icon's
  float w = 1.5 / uResolution.x;
  vec3 col = mix(MP_DEEP, MP_INK, uv.y);
  float s = mix(1.08, 1.0, eOut(ramp(0.45, 1.7)));
  col = mix(col, MP_WHITE, textFill(title, (uv - 0.5) / s + 0.5) * ramp(0.5, 1.1));
  col = mix(col, MP_CYAN, textFill(kicker, uv + vec2(0.0, 0.03 * (1.0 - eOut(ramp(0.9, 1.6))))) * ramp(0.9, 1.5));
  float blue = 1.0 - smoothstep(edge - w, edge + w, uv.x);
  float lensL = (1.0 - smoothstep(edge + bulge - w, edge + bulge + w, uv.x)) * (1.0 - blue);
  float cyan = smoothstep(1.0 - edge - w, 1.0 - edge + w, uv.x);
  float lensR = smoothstep(1.0 - edge - bulge - w, 1.0 - edge - bulge + w, uv.x) * (1.0 - cyan);
  col = mix(col, MP_WHITE, lensL + lensR);
  col = mix(col, MP_BLUE, blue);
  col = mix(col, MP_CYAN, cyan);
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = mpP(fragCoord), uv = fragCoord / uResolution;
  // Starts on the icon exactly as the Construction logo card leaves it, on the same dark ground.
  float z = eInOut(ramp(0.15, 1.45));
  float r = 0.15 * exp(z * 9.0);
  vec2 c = vec2(0.0, 0.07 * (1.0 - z));
  vec3 col = mix(MP_DEEP * 0.75, mix(MP_DEEP, MP_INK, 0.5 + 0.5 * uv.y), z);
  col += MP_CYAN * 0.10 * exp(-abs(p.x) * 9.0) * z;      // light spilling through the gap
  vec4 logo = mpLogo(p, c, r, 0.0, 1.0);
  col = mix(col, logo.rgb, logo.a);
  float a = ramp(1.15, 1.7);
  float s = mix(0.92, 1.0, eOut(ramp(1.15, 2.0)));
  col = mix(col, MP_WHITE, textFill(title, (uv - 0.5) / s + 0.5) * a);
  col = mix(col, MP_CYAN, textFill(kicker, uv) * ramp(1.4, 1.9));
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution, p = mpP(fragCoord);
  vec3 col = MP_INK;
  vec2 g = abs(fract(p * 16.0 + 0.5) - 0.5) / 16.0;
  vec2 g4 = abs(fract(p * 4.0 + 0.5) - 0.5) / 4.0;
  float grid = max(1.0 - smoothstep(0.0, px() * 1.2, min(g.x, g.y)), 0.0) * 0.10;
  grid += (1.0 - smoothstep(0.0, px() * 1.4, min(g4.x, g4.y))) * 0.18;
  float drawn = step(uv.x, eOut(ramp(0.0, 1.0)) * 1.05);
  col = mix(col, MP_BLUE, grid * drawn);
  float scan = mix(-0.05, 1.1, eInOut(ramp(0.35, 1.6)));
  float d = textDistance(title, uv);
  float outline = 1.0 - smoothstep(0.0012, 0.0028, abs(d));
  float traced = step(uv.x, scan);
  col = mix(col, MP_CYAN, outline * traced);
  col = mix(col, MP_WHITE, textFill(title, uv) * ramp(1.5, 2.0));
  col += MP_CYAN * 0.55 * exp(-abs(uv.x - scan) * 220.0) * step(scan, 1.05) * step(0.0, scan);
  col = mix(col, MP_CYAN, textFill(kicker, uv) * step(uv.x, scan) * ramp(0.6, 1.0));
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution;
  vec3 col = mix(MP_DEEP, MP_INK, smoothstep(0.0, 1.0, uv.y));
  float shadow = 0.0;
  for (int i = 0; i < 64; i++) {
    if (i >= titleCount) break;
    vec4 b = titleGlyphs[i];
    float d0 = 0.3 + float(i) * 0.07;
    float k = eBack(ramp(d0, d0 + 0.55));
    float off = (1.0 - k) * 0.22;
    vec2 sp = uv - vec2(0.0, off);
    if (sp.x < b.x - 0.004 || sp.x > b.z + 0.004 || sp.y < b.y - 0.02 || sp.y > b.w + 0.02) continue;
    float a = textFill(title, sp) * ramp(d0, d0 + 0.12);
    vec3 flash = mod(float(i), 2.0) < 0.5 ? MP_BLUE : MP_CYAN;
    vec3 c = mix(flash, MP_WHITE, ramp(d0 + 0.35, d0 + 0.8));
    col = mix(col, c, a);
  }
  // A soft floor shadow the letters land on.
  float floorY = titleBox.y - 0.01;
  col *= 1.0 - 0.25 * exp(-pow((uv.y - floorY) * 60.0, 2.0)) * step(titleBox.x, uv.x) * step(uv.x, titleBox.z) * ramp(0.4, 1.2);
  col = mix(col, MP_CYAN, textFill(kicker, uv) * ramp(1.2, 1.7));
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution;
  vec3 col = MP_INK;
  // The ground is split down the middle too: a hair darker on the left.
  col = mix(col * 0.82, col, smoothstep(0.495, 0.505, uv.x));
  float bands = 9.0;
  float rel = (uv.y - titleBox.y) / max(titleBox.w - titleBox.y, 1e-3);
  float band = floor(clamp(rel, 0.0, 0.999) * bands);
  float side = mod(band, 2.0) < 0.5 ? -1.0 : 1.0;
  float d0 = 0.25 + band * 0.045;
  float k = eOut(ramp(d0, d0 + 0.8));
  vec2 sp = uv + vec2(side * (1.0 - k) * 0.7, 0.0);
  vec3 tint = side < 0.0 ? MP_BLUE : MP_CYAN;
  col = mix(col, mix(tint, MP_WHITE, ramp(d0 + 0.5, d0 + 1.0)), textFill(title, sp) * ramp(d0, d0 + 0.2));
  // The kicker types itself out.
  float typed = mix(kickerBox.x, kickerBox.z + 0.01, ramp(1.2, 1.9));
  col = mix(col, MP_CYAN, textFill(kicker, uv) * step(uv.x, typed));
  float caret = step(abs(uv.x - typed - 0.004), 0.0015) * step(kickerBox.y, uv.y) * step(uv.y, kickerBox.w) * step(1.2, mpT()) * step(fract(mpT() * 2.5), 0.6);
  col = mix(col, MP_CYAN, caret);
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution, p = mpP(fragCoord);
  float t = mpT();
  vec3 col = MP_DEEP;
  float n = fbm(vec2(p.x * 1.6 + t * 0.12, p.y * 2.2 - t * 0.05));
  float m = fbm(vec2(p.x * 2.3 - t * 0.09 + 4.0, p.y * 1.4 + 2.0));
  float band = exp(-pow((p.y + 0.22 - 0.18 * n) * 3.2, 2.0));
  col += MP_BLUE * band * 0.55 * smoothstep(0.3, 0.8, n);
  col += MP_CYAN * band * 0.45 * smoothstep(0.35, 0.85, m);
  col *= ramp(0.0, 0.9);
  float grow = mix(0.009, 0.0, eOut(ramp(0.35, 1.5)));
  float d = textDistance(title, uv);
  float letters = smoothstep(grow - 0.0015, grow + 0.0015, d) * ramp(0.35, 0.6);
  col += MP_CYAN * 0.35 * pow(textHalo(title, uv), 3.0) * ramp(0.4, 1.4);
  col = mix(col, MP_WHITE, letters);
  col = mix(col, MP_CYAN, textFill(kicker, uv) * ramp(1.2, 1.7));
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution, p = mpP(fragCoord);
  float cell = 0.016;
  vec2 id = floor(p / cell), c = (id + 0.5) * cell;
  vec2 cuv = mpUV(c);
  float cov = textFill(title, cuv);
  float bg = 0.12 * smoothstep(0.55, 0.0, length(p - vec2(0.75, -0.4)));   // a faint dot field in the corner
  float h = hash12(id);
  float grow = eOut(ramp(0.2 + h * 0.4, 1.4 + h * 0.3));
  float r = cell * 0.5 * sqrt(max(cov, bg)) * grow * 1.15;
  float dt = cover(length(p - c) - r, px() * 0.8);
  vec3 col = MP_INK;
  vec3 ink = cov > 0.5 ? mix(MP_CYAN, MP_WHITE, ramp(1.0, 1.6)) : MP_BLUE;
  col = mix(col, ink, dt * (cov > 0.5 ? 1.0 : 0.7));
  float solid = ramp(1.6, 2.1);
  col = mix(col, MP_WHITE, textFill(title, uv) * solid);
  col = mix(col, MP_CYAN, textFill(kicker, uv) * ramp(1.6, 2.0));
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution, p = mpP(fragCoord);
  float t = mpT();
  vec3 col = mix(MP_INK, MP_DEEP, length(p));
  for (int i = 0; i < 4; i++) {
    float st = 0.1 + float(i) * 0.22;
    float rr = (t - st) * 0.55;
    float fade = (1.0 - sat((t - st) / 1.8)) * step(st, t);
    col = mix(col, MP_CYAN, (1.0 - smoothstep(0.0, px() * 2.5, abs(length(p) - rr))) * fade * 0.6);
  }
  float d = 0.035 * (1.0 - eOut(ramp(0.3, 1.35)));
  float a = ramp(0.25, 0.6);
  float b = textFill(title, uv + vec2(d, d * 0.3)) * a;
  float c = textFill(title, uv - vec2(d, d * 0.3)) * a;
  vec3 ink = MP_BLUE * b * (1.0 - c) + MP_CYAN * c * (1.0 - b) + MP_WHITE * b * c;
  col = mix(col, ink, max(b, c));
  col = mix(col, MP_CYAN, textFill(kicker, uv) * ramp(1.2, 1.7));
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution, p = mpP(fragCoord);
  float aspect = uResolution.x / uResolution.y;
  float slant = p.x + p.y * 0.45;
  float front = mix(-1.5, 1.9, eInOut(ramp(0.1, 1.4)));
  float band = step(front - 0.55, slant) * step(slant, front);
  vec3 col = MP_INK;
  float behind = step(slant, front - 0.55);
  col = mix(col, MP_WHITE, textFill(title, uv) * behind);
  // The tag: a cyan pill with dark words.
  vec2 k0 = kickerBox.xy - vec2(0.012, 0.018), k1 = kickerBox.zw + vec2(0.012, 0.018);
  vec2 kc = (k0 + k1) * 0.5, kh = (k1 - k0) * 0.5;
  float pd = sdRBox((uv - kc) * vec2(aspect, 1.0), kh * vec2(aspect, 1.0), 0.02);
  float pill = cover(pd, px()) * behind * ramp(1.2, 1.5);
  col = mix(col, MP_CYAN, pill);
  col = mix(col, MP_INK, textFill(kicker, uv) * pill);
  float s = fract(slant * 9.0);
  vec3 stripe = s < 0.45 ? MP_BLUE : (s < 0.9 ? MP_CYAN : MP_WHITE);
  col = mix(col, stripe, band);
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution, p = mpP(fragCoord);
  float k = ramp(0.2, 1.5);
  float stepN = floor(k * 6.0);
  float cell = 0.12 * pow(0.5, stepN);
  vec2 id = floor(p / cell), c = (id + 0.5) * cell;
  float cov = textFill(title, mpUV(c));
  // Wider blocks average more of the letters, so sample a few points in the block.
  cov = (cov + textFill(title, mpUV(c + cell * vec2(0.3, 0.3))) + textFill(title, mpUV(c - cell * vec2(0.3, 0.3)))
        + textFill(title, mpUV(c + cell * vec2(0.3, -0.3))) + textFill(title, mpUV(c + cell * vec2(-0.3, 0.3)))) / 5.0;
  float h = hash12(id + stepN * 7.0);
  vec3 tint = h < 0.5 ? MP_BLUE : MP_CYAN;
  vec3 col = MP_INK + (h - 0.5) * 0.03;
  float sharp = step(5.5, k * 6.0);
  vec3 ink = mix(tint, MP_WHITE, ramp(1.1, 1.6));
  col = mix(col, ink, mix(cov, textFill(title, uv), sharp) * step(0.01, k));
  col = mix(col, MP_CYAN, textFill(kicker, uv) * ramp(1.5, 1.9));
  fragColor = vec4(col, 1.0 - ramp(uDuration - 0.5, uDuration));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution;
  float t = mpT();
  float edge = 0.5 * eInOut(ramp(0.0, 0.9));
  edge = mix(edge, 0.06, eInOut(ramp(1.1, 1.9)));
  float yy = (uv.y - 0.5) * 2.0;
  float bulge = 0.07 * sqrt(max(0.0, 1.0 - yy * yy)) * mix(1.0, 0.4, ramp(1.1, 1.9));
  float w = 1.5 / uResolution.x;
  float shut = step(0.9, t);
  vec4 col = vec4(mix(MP_DEEP, MP_INK, uv.y), shut);
  col.rgb = mix(col.rgb, MP_CYAN, textFill(kicker, uv) * ramp(1.5, 2.0));
  col.rgb = mix(col.rgb, MP_WHITE, textFill(next, uv + vec2(0.0, 0.02 * (1.0 - eOut(ramp(1.6, 2.4))))) * ramp(1.6, 2.1));
  float blue = 1.0 - smoothstep(edge - w, edge + w, uv.x);
  float lensL = (1.0 - smoothstep(edge + bulge - w, edge + bulge + w, uv.x)) * (1.0 - blue) * step(0.001, edge);
  float cyan = smoothstep(1.0 - edge - w, 1.0 - edge + w, uv.x);
  float lensR = smoothstep(1.0 - edge - bulge - w, 1.0 - edge - bulge + w, uv.x) * (1.0 - cyan) * step(0.001, edge);
  col = over(vec4(MP_WHITE, lensL + lensR), col);
  col = over(vec4(MP_BLUE, blue), col);
  col = over(vec4(MP_CYAN, cyan), col);
  fragColor = col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution, p = mpP(fragCoord);
  float aspect = uResolution.x / uResolution.y;
  float dim = 0.6 * ramp(0.0, 0.6);
  vec4 col = vec4(MP_DEEP, dim);
  float k = eOut(ramp(0.3, 1.0));
  float sx = (1.0 - k) * 0.5;
  vec2 a = vec2(0.565, 0.33), b = vec2(0.93, 0.68);
  vec2 cc = (a + b) * 0.5 + vec2(sx, 0.0), hh = (b - a) * 0.5;
  float d = sdRBox((uv - cc) * vec2(aspect, 1.0), hh * vec2(aspect, 1.0), 0.025);
  float card = cover(d, px());
  col = over(vec4(MP_INK, card * 0.96), col);
  col = over(vec4(MP_CYAN, (1.0 - smoothstep(0.0, px() * 1.5, abs(d))) * 0.6 * card), col);
  col = over(vec4(MP_CYAN, textFill(kicker, uv - vec2(sx, 0.0))), col);
  col = over(vec4(MP_WHITE, textFill(next, uv - vec2(sx, 0.0))), col);
  float prog = ramp(1.0, uDuration - 0.4);
  float barY = 0.385, x0 = 0.6 + sx, x1 = 0.895 + sx;
  float bar = step(abs(uv.y - barY), 0.004) * step(x0, uv.x) * step(uv.x, x1);
  col = over(vec4(MP_WHITE, bar * 0.15 * k), col);
  col = over(vec4(MP_CYAN, bar * step(uv.x, mix(x0, x1, prog)) * k), col);
  vec4 lg = mpLogo(p, vec2(-0.78, 0.4), 0.035, 0.0, 1.0);
  col = over(vec4(lg.rgb, lg.a * ramp(0.4, 0.9)), col);
  // At the very end the whole frame goes to the ground colour.
  col = over(vec4(MP_INK, ramp(uDuration - 0.6, uDuration)), col);
  fragColor = col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / uResolution, p = mpP(fragCoord);
